/**
 * Convenience type for vertical slider.
 * See https://github.com/phetsims/sun/issues/380
 *
 * @author Chris Malley (PixelZoom, Inc.)
 */
import '../../globals.js';
import '../../chipper/js/browser/initialize-globals.js';
import { assert } from '../../scenerystack/assert.js';
import InstanceRegistry from '../../phet-core/js/documentation/InstanceRegistry.js';
import optionize from '../../phet-core/js/optionize.js';
import Orientation from '../../phet-core/js/Orientation.js';
import { default as Slider } from './Slider.js';
import sun from './sun.js';
export default class VSlider extends Slider {
    constructor(valueProperty, range, options) {
        options = optionize()({
            orientation: Orientation.VERTICAL
        }, options);
        super(valueProperty, range, options);
        // support for binder documentation, stripped out in builds and only runs when ?binder is specified
        assert && self.phet?.chipper?.queryParameters?.binder && InstanceRegistry.registerDataURL('sun', 'VSlider', this);
    }
}
sun.register('VSlider', VSlider);
